# Packed from 03_unpack_kmc_files.sh

#!/bin/sh

###
# Fix permissions for KMC (MKK doesn't need this)
###
log "Checking storage..."
# We track how much storage the currently installed hotfix/monolith takes (since we're gonna delete it, it shouldn't count)
STORAGE_FREEABLE=$((0))

log "Reading storage from folders"
if [ -d "/var/local/kmc" ]; then
    STORAGE_FREEABLE=$(($STORAGE_FREEABLE + $(du -ks /var/local/kmc | cut -f1)))
fi
if [ -d "/var/local/mkk" ]; then
    STORAGE_FREEABLE=$(($STORAGE_FREEABLE + $(du -ks /var/local/mkk | cut -f1)))
fi

# Make sure we have enough space in /var/local to unpack our KMC and MKK tars
if [ "$(df -k /var/local | tail -n 1 | tr -s ' ' | cut -d' ' -f4)" -lt "$(($(du -ks /tmp/kmc | cut -f1) - $STORAGE_FREEABLE))" ] ; then
    log "not enough space left in varlocal"
    log "Needed: $(($(du -ks /tmp/kmc | cut -f1) - $STORAGE_FREEABLE))"
    log "Available: $(df -k /var/local | tail -n 1 | tr -s ' ' | cut -d' ' -f4)"
    rm -rf /tmp/kmc
    return 1
fi

log "Removing mkk"
make_mutable /var/local/mkk
rm -rf /var/local/mkk
mkdir /var/local/mkk

log "Removing kmc"
make_mutable /var/local/kmc
rm -rf /var/local/kmc
mkdir /var/local/kmc

log "Unpacking KMC"
make_mutable "/var/local/kmc"
cp -rf /tmp/kmc/* /var/local/kmc
rm -rf /tmp/kmc
# Packed from 04_setup_kmc.sh

#!/bin/sh
log "Setting KMC permissions"
chmod -R a+rx /var/local/kmc/sbin/*
chmod -R a+rx /var/local/kmc/kindlepw2/*
chmod -R a+rx /var/local/kmc/kindlehf/*
chmod 0664 /var/local/kmc/system_patches/kmc.conf
chmod a+rx /var/local/kmc/system_patches/patch_system.sh
chmod a+rx /var/local/kmc/system_patches/run_patch.sh

log "Setting KMC gandalf permissions"
for gandalf_platform in kindlepw2 kindlehf; do
    make_mutable "/var/local/kmc/${gandalf_platform}/bin/gandalf"
    chown root:root "/var/local/kmc/${gandalf_platform}/bin/gandalf"
    chmod a+rx "/var/local/kmc/${gandalf_platform}/bin/gandalf"
    chmod +s "/var/local/kmc/${gandalf_platform}/bin/gandalf"
    ln -sf "/var/local/kmc/${gandalf_platform}/bin/gandalf" "/var/local/kmc/${gandalf_platform}/bin/su"
    make_immutable "/var/local/kmc/${gandalf_platform}/bin/gandalf"
done


log "Establishing Gandalf links"
rm -rf "/var/local/kmc/lib"
rm -rf "/var/local/kmc/bin"
ln -sf "/var/local/kmc/${PLATFORM}/lib" "/var/local/kmc/lib"
ln -sf "/var/local/kmc/${PLATFORM}/bin" "/var/local/kmc/bin"
ln -sf "/var/local/kmc/bin/gandalf" "/var/local/mkk/gandalf"
make_mutable /var/local/mkk
ln -sf "/var/local/mkk/gandalf" "/var/local/mkk/su"
make_immutable /var/local/mkk
make_immutable /var/local/kmc
# Since the links to these binaries are SOFT links, no additional copying/linking is required

log "Installing libkh binaries"
mkdir -p "/mnt/us/libkh/bin"
rm -f /mnt/us/libkh/bin/fbink
cp -f "/var/local/kmc/${PLATFORM}/bin/fbink" "/mnt/us/libkh/bin/fbink" # Yeah we do copying bc userstore is funky
chmod a+rx "/mnt/us/libkh/bin/fbink"

log "Deleting old hotfix"
rm /mnt/us/documents/*.run_hotfix

log "Setting up hotfix and emergency runners"
log "$(cat /var/local/kmc/sql/appreg_register_hotfix.sql | sqlite3 /var/local/appreg.db)"
log "$(cat /var/local/kmc/sql/appreg_register_emergency.sql | sqlite3 /var/local/appreg.db)"

if [ ! -d "/usr/lib/ccat" ]; then
    log "Setting up sh_integration"
    log "$(cat /var/local/kmc/sql/appreg_register_sh_integration_common.sql | sqlite3 /var/local/appreg.db)"
    log "$(cat /var/local/kmc/sql/appreg_register_sh_integration_1.sql | sqlite3 /var/local/appreg.db)"
    NUM=$(echo "SELECT * FROM properties WHERE handlerId='tech.hackerdude.shell_integration.extractor'" | sqlite3 /var/local/appreg.db --line | wc -l)
    if [ ! $NUM -eq 7 ]; then
        log "Failed to setup sh_integration, trying again..."
        sleep 1
        log "$(cat /var/local/kmc/sql/appreg_register_sh_integration_common.sql | sqlite3 /var/local/appreg.db)"
        log "$(cat /var/local/kmc/sql/appreg_register_sh_integration_1.sql | sqlite3 /var/local/appreg.db)"
        NUM=$(echo "SELECT * FROM properties WHERE handlerId='tech.hackerdude.shell_integration.extractor'" | sqlite3 /var/local/appreg.db --line | wc -l)
        if [ ! $NUM -eq 7 ]; then
            log "Failed to setup sh_integraion - please report to Hackerdude"
        fi
    fi
else
    log "/usr/lib/ccat detected - deferring sh_integration setup to system patch stage"
fi
# Packed from 05_install_mkk_dev_keystore.sh

#!/bin/sh

# Check if we need to do something with the Kindlet developer keystore
# No developer keystore, install it                       		OR  The developer keystore doesn't match - NOTE: This *will* mess with real, official developer keystores. Not that we really care about it, but it should be noted ;).
if [ ! -f "/var/local/java/keystore/developer.keystore" ] || \
	[ "$(md5sum "/var/local/java/keystore/developer.keystore" | cut -d' ' -f1)" != "$(md5sum "/var/local/kmc/system_patches/developer.keystore" | cut -d' ' -f1)" ] ; then
	
	# Install the kindlet keystore
	log "Copying the kindlet keystore"
	# We shouldn't need to do anything specific to read/write /var/local
	if [ "$(df -k /var/local | tail -n 1 | tr -s ' ' | cut -d' ' -f4)" -lt "512" ] ; then
		log "Failed to copy the kindlet keystore: not enough space left on device"
		# THIS SHOULD NOT BE POSSIBLE???
	else
		# NOTE: This might have gone poof on newer devices without Kindlet support, so, create it as needed
		mkdir -p "/var/local/java/keystore"
		cp -f "/var/local/kmc/system_patches/developer.keystore" "/var/local/java/keystore/developer.keystore"
	fi
fi
# Packed from 06_patch_system.sh

#!/bin/sh

# Check if we need to do something with the Kindlet developer keystore
# No developer keystore, install it                       		OR  The developer keystore doesn't match - NOTE: This *will* mess with real, official developer keystores. Not that we really care about it, but it should be noted ;).
if [ ! -f "/var/local/java/keystore/developer.keystore" ] || \
	[ "$(md5sum "/var/local/java/keystore/developer.keystore" | cut -d' ' -f1)" != "$(md5sum "/var/local/kmc/system_patches/developer.keystore" | cut -d' ' -f1)" ] ; then
	
	# Install the kindlet keystore
	log "Copying the kindlet keystore"
	# We shouldn't need to do anything specific to read/write /var/local
	if [ "$(df -k /var/local | tail -n 1 | tr -s ' ' | cut -d' ' -f4)" -lt "512" ] ; then
		log "Failed to copy the kindlet keystore: not enough space left on device"
		# THIS SHOULD NOT BE POSSIBLE???
	else
		# NOTE: This might have gone poof on newer devices without Kindlet support, so, create it as needed
		mkdir -p "/var/local/java/keystore"
		cp -f "/var/local/kmc/system_patches/developer.keystore" "/var/local/java/keystore/developer.keystore"
	fi
fi

# Run system patch script (what was once the hotfix)

# Detect rootless Kindle
if [ $ROOTLESS -eq 0 ]; then
	log "Running system patch script"
	ROOTLESS=$ROOTLESS RUN_MODE=$RUN_MODE JAILBROKEN=$JAILBROKEN sh /var/local/kmc/system_patches/patch_system.sh # Run it directly since jb.sh MUST be run as root
else
	log "Running on rootless system with dmverity, skipping system patches"
fi
# Packed from 07_cleanup.sh

/bin/mount -o remount,ro /
/bin/mount -o exec /mnt/us # Remount as exec
log "Done"

if [ $RUN_MODE -eq 1 ] || [ $JAILBROKEN -eq 0 ]; then
    printf "You are jailbroken!\n" > /mnt/us/documents/JAILBROKEN.txt
    printf "(jb.sh $JB_SH_VERSION)\n" >> /mnt/us/documents/JAILBROKEN.txt
    printf "https://kindlemodding.org\n" >> /mnt/us/documents/JAILBROKEN.txt
    printf "https://hackerdude.tech\n" >> /mnt/us/documents/JAILBROKEN.txt
    printf "\n" >> /mnt/us/documents/JAILBROKEN.txt
    printf "$JB_HEADER" >> /mnt/us/documents/JAILBROKEN.txt
    printf "$JB_HEADER" > /var/local/jailbreak.txt

    log "Restarting GUI..." # Necessary for sh_integration
    sleep 2 # So they can read what's about to happen
    lipc-set-prop com.lab126.appmgrd start app://com.lab126.booklet.home
    lipc-set-prop com.lab126.appmgrd start app://com.lab126.KPPMainApp?view=KPP_HOME
    if [ -f "/etc/upstart/kppmainapp.conf" ] ; then
        log "Restart strategy 1"
        restart lab126_gui &
        sleep 3 # Wait for it to stop
    elif [ -f "/etc/upstart/acxe.conf" ] ; then
        log "Restart strategy 2"
        restart acxe & # On older devices restart the entire gui
        sleep 3 # Wait for it to stop
    else
        log "Restart strategy 3"
        telinit 5 &
        sleep 3 # Wait for it to stop
    fi
    /var/local/kmc/bin/fbink -y 3 -m -S 7 "Restarting GUI"
    /var/local/kmc/bin/fbink -y 4 -m -S 7 "Please Wait..."
    /var/local/kmc/bin/fbink -y 16 -p -S 3 "(Kindles are slow lol)  "
    /var/local/kmc/bin/fbink -y -6 -m -S 4 "(Error dialog is fine)"
    /var/local/kmc/bin/fbink -y -5 -m -S 4 "(Just press close and keep waiting!)"
    
fi